{
  "requirement_definitions": [
    {
      "id": "DMSR-5225",
      "title": "Level 1 Processing of Special Programs Data",
      "text": "All Level 1 processing from special programs shall be completed before data arrives from the following night’s observations."
    },
    {
      "id": "DMSR-6637",
      "title": "Constraints on Level 1 Special Program Products Generation",
      "text": "The publishing of Level 1 data products from Special Programs shall be subject to the same performance requirements of the standard Level 1 system. In particular L1PublicT and OTT1."
    },
    {
      "id": "DMSR-4733",
      "title": "Special Programs Database",
      "text": "Data products for special programs shall be stored in databases that are distinct from those used to store standard Level 1 and Level 2 data products. It shall be possible for these databases to be federated with the Level 1 and Level 2 databases to allow crossqueries and joins."
    },
    {
      "id": "DMSR-6832",
      "title": "Query Repeatability",
      "text": "The DMS shall ensure that any query executed at a particular point in time against any DMS delivered database shall be repeatable at a later date, and produce results that are either identical or include additional results (owing to updates from Level-1 processing)."
    },
    {
      "id": "DMSR-1188",
      "title": "Uniqueness of IDs Across Data Releases",
      "text": "To reduce the likelihood for confusion, all IDs shall be unique across databases and database versions, other than those corresponding to uniquely identiﬁable entities (i.e., IDs of exposures)."
    },
    {
      "id": "DMSR-7045",
      "title": "Selection of Datasets",
      "text": "A Dataset may consist of one or more pixel images, a set of records in a ﬁle or database, or any other grouping of data that are processed or produced as a logical unit. The DMS shall be able to identify and retrieve complete, consistent datasets for processing."
    },
    {
      "id": "DMSR-9393",
      "title": "Processing of Datasets",
      "text": "The DMS shall process all requested datasets until either a successful result is recorded or a permanent failure is recognized. If any dataset is processed, in part or in whole, more than once, only one of the wholly processed results will be recorded for further processing."
    }
  ],
